describe('Payment Card Decline Error Handling', () => {
  beforeEach(() => {
    cy.visit('/payment');
  });

  it('should display clear error message when payment card is declined', () => {
    // Intercept the payment API call and simulate a decline response
    cy.intercept('POST', '/api/payment/process', {
      statusCode: 422,
      body: {
        error: 'Card declined',
        errorCode: 'DECLINED_CARD',
        message: 'Your payment card was declined. Please check your card details or use a different card.'
      }
    }).as('paymentDeclined');

    // Fill in valid card details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');
    cy.get('[data-testid="card-holder-name-input"]').type('John Doe');

    // Click the pay button
    cy.get('[data-testid="pay-button"]').click();

    // Wait for the API call
    cy.wait('@paymentDeclined');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Your payment card was declined');

    // Verify error details are present
    cy.get('[data-testid="error-code"]')
      .should('be.visible')
      .should('contain', 'DECLINED_CARD');

    // Verify error icon is displayed
    cy.get('[data-testid="error-icon"]')
      .should('be.visible');

    // Verify form is still visible for retry
    cy.get('[data-testid="card-number-input"]').should('be.visible');
  });

  it('should handle multiple decline attempts and provide retry option', () => {
    // Intercept the first two payment attempts and simulate decline
    cy.intercept('POST', '/api/payment/process', {
      statusCode: 422,
      body: {
        error: 'Card declined',
        errorCode: 'DECLINED_CARD',
        message: 'Your payment card was declined. Please check your card details or use a different card.'
      }
    }).as('paymentDeclinedAttempt1');

    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');
    cy.get('[data-testid="card-holder-name-input"]').type('John Doe');

    // First attempt
    cy.get('[data-testid="pay-button"]').click();
    cy.wait('@paymentDeclinedAttempt1');

    // Verify error message appears
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Your payment card was declined');

    // Retry with the same card
    cy.get('[data-testid="pay-button"]').click();

    // Intercept the second attempt
    cy.intercept('POST', '/api/payment/process', {
      statusCode: 422,
      body: {
        error: 'Card declined',
        errorCode: 'DECLINED_CARD',
        message: 'Your payment card was declined. Please check your card details or use a different card.'
      }
    }).as('paymentDeclinedAttempt2');

    cy.wait('@paymentDeclinedAttempt2');

    // Verify error message persists and retry button is available
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Your payment card was declined');

    cy.get('[data-testid="retry-button"]')
      .should('be.visible')
      .should('contain', 'Try Again');

    // Verify form fields are still populated for quick retry
    cy.get('[data-testid="card-number-input"]').should('have.value', '4111111111111111');
  });
});
